import { IngestPipeline } from "@514labs/moose-lib";

// User Activity Event Data Model
export interface UserActivity {
  eventId: string;
  eventTs: Date;
  userId: string;
  action: string;
  durationMs?: number; // Nullable, will default to 0
}

// Ingest Pipeline with ClickHouse table optimized for our query patterns:
// 1. Activity counts per user over a date range (userId, eventTs)
// 2. Total duration per action type (action)
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["userId", "eventTs", "action"] // Optimized for both query patterns
  },
  stream: true,
  ingestApi: true,
});

